-- Friend requests and friendships. One row per pair: requester asks, addressee accepts (ACCEPTED) or the row is deleted.
CREATE TABLE IF NOT EXISTS "public"."friendships" (
  "id"           bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"   timestamp with time zone NOT NULL DEFAULT now(),
  "requester_id" bigint                   NOT NULL,
  "addressee_id" bigint                   NOT NULL,
  "status"       text                     NOT NULL DEFAULT 'PENDING',
  "accepted_at"  timestamp with time zone,
  CONSTRAINT "friendships_pkey" PRIMARY KEY (id),
  CONSTRAINT "friendships_requester_id_fkey" FOREIGN KEY (requester_id) REFERENCES public.users(id) ON DELETE CASCADE,
  CONSTRAINT "friendships_addressee_id_fkey" FOREIGN KEY (addressee_id) REFERENCES public.users(id) ON DELETE CASCADE,
  CONSTRAINT "chk_friendships_not_self" CHECK ((requester_id <> addressee_id)),
  CONSTRAINT "chk_friendships_status" CHECK ((status IN ('PENDING', 'ACCEPTED')))
);

-- A pair can only have one row, whoever asked first.
CREATE UNIQUE INDEX IF NOT EXISTS "uq_friendships_pair"
  ON "public"."friendships" (LEAST(requester_id, addressee_id), GREATEST(requester_id, addressee_id));

CREATE INDEX IF NOT EXISTS "idx_friendships_addressee" ON "public"."friendships" (addressee_id);

-- Only the backend (postgres role) writes; users may read their own rows.
ALTER TABLE "public"."friendships"
  ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Ver mis propias amistades" ON "public"."friendships";
CREATE POLICY "Ver mis propias amistades" ON "public"."friendships"
  FOR SELECT
  TO "authenticated"
  USING (((requester_id = public.get_current_user_id()) OR (addressee_id = public.get_current_user_id())));
